<script setup lang="ts">
/**
 * A settings row: label and description beside one control (`design/components/settings-row.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/settings-row.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { cloneVNode, computed, useId } from 'vue'

import { definedProps, slottedElements } from '@polymorph/vue'
import styles from '@polymorph/recipes/structure/settings-row.module.css'
import type { SettingsRowGroupProps } from './SettingsRowGroup.vue'

export type SettingsGroupProps = SettingsRowGroupProps

export interface SettingsRowProps {
  description?: string
  label: string
}

defineOptions({ name: 'SettingsRow', inheritAttrs: false })

defineProps<SettingsRowProps>()
defineSlots<{ control: (props: Record<string, never>) => unknown }>()
const uid = useId()
const labelId = computed(() => `${uid}-label`)
const descriptionId = computed(() => `${uid}-description`)
</script>

<template>
  <div :class="styles.row" data-member="settings-row">
    <div :class="styles.text">
      <span :class="styles.label" :id="labelId">
        {{ label }}
      </span>
      <span v-if="description !== undefined" :class="styles.description" :id="descriptionId">
        {{ description }}
      </span>
    </div>
    <div :class="styles.control">
      <template v-for="(node, at) in slottedElements($slots.control)" :key="at">
        <component
          :is="
            cloneVNode(
              node,
              definedProps({
                'aria-labelledby': labelId,
                'aria-describedby': description === undefined ? undefined : descriptionId,
              }),
            )
          "
        />
      </template>
    </div>
  </div>
</template>
